# Generated by manage.py generate_test_cases.
from datetime import timedelta
from functools import partial
from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.models.document_signing.signature_recipient import SignatureRecipient
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .support import SigningFixturesMixin


class TestSignatureRecipientModel(SigningFixturesMixin, BloomerpModelTestCase):
    """Cover external signer snapshots, explicit consent, and ordered responses."""

    model = SignatureRecipient

    def prepare_signing(self, recipient: SignatureRecipient) -> None:
        """Add this scenario's recipient fields before dispatching the shared request."""
        self.active_recipient = recipient
        self.create_field(recipient)
        self.dispatch_request(self.request)

    def prepare_signed(self, recipient: SignatureRecipient) -> None:
        """Finalize a recipient whose subsequent response must be immutable."""
        self.prepare_signing(recipient)
        self.sign_recipient(recipient)

    def signing_args(self, fill: bool = True, **overrides: Any) -> dict[str, Any]:
        """Optionally fill fields and return retained consent and signing metadata."""
        if fill:
            self.fill_recipient_fields(self.active_recipient)
        return {
            "status": SignatureRecipient.Status.SIGNED,
            "consent_text": "I agree to sign this document electronically.",
            "consented_at": self.now + timedelta(seconds=2),
            "signed_at": self.now + timedelta(seconds=3),
            **overrides,
        }

    def validate_signed(self, recipient: SignatureRecipient) -> bool:
        """Verify that an external email signer retains consent and a response time."""
        return (
            recipient.status == SignatureRecipient.Status.SIGNED
            and recipient.signed_at is not None
            and bool(recipient.consent_text)
        )

    def get_test_scenarios(self) -> list[ModelScenario[SignatureRecipient]]:
        """Exercise consent, request state, required fields, and signing order."""
        return [
            ModelScenario(
                name="Create an external signer without a user account",
                create_args=self.recipient_args,
            ),
            ModelScenario(
                name="Reject duplicate role assignments in one request",
                create_args=partial(
                    self.recipient_args, role_key=self.recipient.role_key
                ),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Accept explicit consent and completed fields",
                create_args=self.recipient_args,
                post_create=self.prepare_signing,
                update_args=self.signing_args,
                update_validators=self.validate_signed,
            ),
            ModelScenario(
                name="Require explicit consent text",
                create_args=self.recipient_args,
                post_create=self.prepare_signing,
                update_args=partial(self.signing_args, consent_text=""),
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Require completed mandatory fields",
                create_args=self.recipient_args,
                post_create=self.prepare_signing,
                update_args=partial(self.signing_args, fill=False),
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Wait for earlier signing groups",
                create_args=partial(self.recipient_args, signing_order=2),
                post_create=self.prepare_signing,
                update_args=self.signing_args,
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Freeze recipient identity after dispatch",
                create_args=self.recipient_args,
                post_create=self.prepare_signing,
                update_args={"email": "replacement@example.com"},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Retain a final signing response",
                create_args=self.recipient_args,
                post_create=self.prepare_signed,
                update_args={"status": SignatureRecipient.Status.PENDING},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Reject consent predating dispatch",
                create_args=self.recipient_args,
                post_create=self.prepare_signing,
                update_args=partial(
                    self.signing_args, consented_at=self.now - timedelta(seconds=1)
                ),
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Reject recipients added after dispatch",
                preparation=partial(self.dispatch_request, self.request),
                create_args=self.recipient_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
        ]

    def test_partial_save_validates_the_actual_persisted_consent(self) -> None:
        """Reject partial writes that would retain consent text without its time."""
        self.dispatch_request(self.request)
        self.recipient.consent_text = "I agree to sign electronically."
        self.recipient.consented_at = self.now
        with self.assertRaises(ValidationError):
            self.recipient.save(update_fields=["consent_text"])
        self.recipient.refresh_from_db()
        self.assertEqual(self.recipient.consent_text, "")
        self.assertIsNone(self.recipient.consented_at)
